import { createHash, randomUUID } from "node:crypto";
import type { BusinessSession, BusinessSessionRunner } from "../ports/persistence.ts";
import type { BookSetId, TenantId } from "../../core/types.ts";
import { brandAccountId, DomainError, IdempotencyConflictError, IdempotencyCorruptError } from "../../core/types.ts";
import type { CommandEnvelope, CommandResult } from "../commands.ts";
import { canonicalJson, computeCommandHash, computeResultHash } from "../commands.ts";
import { validateCommandEnvelope } from "./bookset-command-service.ts";
import { postJournalInSession } from "./journal-command-service.ts";

export type BookPolicyMethod = "STRAIGHT_LINE" | "REDUCING_BALANCE";
export type BookPolicyFramework = "AS_10" | "IND_AS_16" | "COMPANIES_ACT_SCHEDULE_II" | "CUSTOM_SUPPORTED";
export type ProrataConvention = "DAILY_ACTUAL_365" | "DAILY_ACTUAL_366" | "MONTHLY" | "FULL_MONTH";
export type RoundingPolicy = "PAISE_HALF_UP" | "PAISE_DOWN" | "PAISE_UP";

export interface AssetBookPolicyPayload {
  framework: BookPolicyFramework; sourceReference: string; effectiveFrom: string; effectiveTo?: string;
  method: BookPolicyMethod; usefulLifeMonths: number; residualMinor: number;
  prorataConvention: ProrataConvention; roundingPolicy: RoundingPolicy; remainderPolicy: "FINAL_PERIOD" | "PRO_RATA_FINAL_DAY";
  reducingRateBps?: number; justification: string;
}
export interface AssetComponentPayload { description: string; costMinor: number; residualMinor: number; usefulLifeMonths: number; method: BookPolicyMethod; reducingRateBps?: number; }
export interface AssetRegisterPayload {
  assetNumber: string; acquisitionDate: string; putToUseDate: string; description: string; category?: string; location?: string; custodian?: string;
  costMinor: number; businessUseBps: number; assetAccountId: string; accumulatedDepreciationAccountId: string; depreciationExpenseAccountId: string; gainLossAccountId: string;
  bookPolicy: AssetBookPolicyPayload; components?: AssetComponentPayload[]; vendorBillLineId?: string; acquisitionJournalId?: string; evidenceReference?: string; taxBlockId?: string;
}
export interface AssetRegisterResult { assetId: string; assetNumber: string; costMinor: number; status: "ACTIVE"; }
export interface DepreciationPreviewPayload { periodStart: string; periodEnd: string; }
export interface DepreciationLineResult { assetId: string; assetNumber: string; amountMinor: number; openingAccumulatedMinor: number; closingAccumulatedMinor: number; calculationFacts: Record<string, unknown>; }
export interface DepreciationResult { runId: string; periodStart: string; periodEnd: string; totalMinor: number; status: "PREVIEW" | "POSTED" | "NO_OP"; journalId?: string; lines: DepreciationLineResult[]; }
export interface AssetTaxRulePayload { lawName: string; ruleReference: string; version: string; sourceUrl: string; effectiveFrom: string; effectiveTo?: string; blockCode: string; rateBps: number; halfRateCondition: string; calculationFacts?: Record<string, unknown>; sourceVerified: boolean; }
export interface TaxRuleResult { ruleSnapshotId: string; blockCode: string; canonicalHash: string; }
export interface TaxBlockPayload { blockCode: string; ruleSnapshotId: string; openingWdvMinor: number; }
export interface TaxBlockResult { blockId: string; blockCode: string; openingWdvMinor: number; }
export interface TaxComputePayload { periodStart: string; periodEnd: string; additionFacts?: Record<string, { halfRate: boolean }>; }
export interface TaxLineResult { blockId: string; blockCode: string; openingWdvMinor: number; additionsFullMinor: number; additionsHalfMinor: number; businessUseBps: number; disposalConsiderationMinor: number; depreciationMinor: number; closingWdvMinor: number; cessation: boolean; negativeProceeds: boolean; calculationFacts: Record<string, unknown>; }
export interface TaxRunResult { runId: string; periodStart: string; periodEnd: string; lines: TaxLineResult[]; }
export interface AssetDisposePayload { assetId: string; disposalDate: string; proceedsMinor: number; proceedsAccountId: string; evidenceReference: string; }
export interface AssetDisposeResult { disposalId: string; assetId: string; carryingAmountMinor: number; gainLossMinor: number; journalId: string; status: "DISPOSED"; }
export interface AssetRegisterRow { assetId: string; assetNumber: string; acquisitionDate: string; putToUseDate: string; description: string; category?: string; costMinor: number; accumulatedDepreciationMinor: number; carryingAmountMinor: number; status: string; disposedAt?: string; }

type ScopedEnvelope<P> = CommandEnvelope<P> & { bookSetId: BookSetId };
type StoredIdempotency = { requestHash: string; resultJson: string; resultHash: string };

function date(value: unknown, field: string): asserts value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new DomainError("INVALID_DATE", `${field} must be YYYY-MM-DD`);
  const parsed = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value) throw new DomainError("INVALID_DATE", `${field} must be a valid ISO date`);
}
function positive(value: unknown, field: string): number { if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) throw new DomainError("INVALID_AMOUNT", `${field} must be a positive safe integer`); return value; }
function nonnegative(value: unknown, field: string): number { if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) throw new DomainError("INVALID_AMOUNT", `${field} must be a non-negative safe integer`); return value; }
function boundedText(value: unknown, field: string, max = 4096): string { if (typeof value !== "string" || value.trim() === "" || value.length > max) throw new DomainError("INVALID_FIELD", `${field} must be nonblank and bounded`); return value; }
function safeAdd(a: number, b: number): number { const n = a + b; if (!Number.isSafeInteger(n)) throw new DomainError("INVALID_AMOUNT", "amount exceeds safe integer range"); return n; }
function assertEnvelope<P>(e: ScopedEnvelope<P>): void { validateCommandEnvelope(e); if (typeof e.bookSetId !== "string" || e.bookSetId.length === 0) throw new DomainError("INVALID_BOOK_SET_ID", "bookSetId is required"); }
function daysInYear(year: number): number { return new Date(Date.UTC(year + 1, 0, 1)).getTime() - new Date(Date.UTC(year, 0, 1)).getTime() > 365 * 86400000 ? 366 : 365; }
function utcDate(value: string): Date { return new Date(`${value}T00:00:00.000Z`); }
function inclusiveDays(from: string, to: string): number { return Math.floor((utcDate(to).getTime() - utcDate(from).getTime()) / 86400000) + 1; }
function maxDate(a: string, b: string): string { return a > b ? a : b; }
function minDate(a: string, b: string): string { return a < b ? a : b; }
function roundPaise(numerator: number, denominator: number, policy: RoundingPolicy): number {
  if (denominator <= 0) throw new DomainError("INVALID_DEPRECIATION_POLICY", "rounding denominator must be positive");
  if (policy === "PAISE_DOWN") return Math.floor(numerator / denominator);
  if (policy === "PAISE_UP") return Math.ceil(numerator / denominator);
  return Math.floor((numerator + Math.floor(denominator / 2)) / denominator);
}

export interface DepreciationCalculationInput { costMinor: number; residualMinor: number; accumulatedMinor: number; method: BookPolicyMethod; usefulLifeMonths: number; reducingRateBps?: number; periodStart: string; periodEnd: string; putToUseDate: string; prorataConvention: ProrataConvention; roundingPolicy: RoundingPolicy; }
export interface DepreciationCalculation { amountMinor: number; closingAccumulatedMinor: number; eligibleDays: number; denominatorDays: number; fractionNumerator: number; fractionDenominator: number; }

/** Pure, integer-paise book depreciation calculation. */
export function calculateBookDepreciation(input: DepreciationCalculationInput): DepreciationCalculation {
  date(input.periodStart, "periodStart"); date(input.periodEnd, "periodEnd"); date(input.putToUseDate, "putToUseDate");
  if (input.periodEnd < input.periodStart) throw new DomainError("INVALID_PERIOD", "periodEnd must not precede periodStart");
  const depreciable = input.costMinor - input.residualMinor;
  if (depreciable < 0 || input.accumulatedMinor < 0 || input.accumulatedMinor > depreciable) throw new DomainError("INVALID_DEPRECIATION_STATE", "accumulated depreciation is outside the depreciable amount");
  const start = maxDate(input.periodStart, input.putToUseDate);
  const end = input.periodEnd;
  if (start > end || input.accumulatedMinor === depreciable) return { amountMinor: 0, closingAccumulatedMinor: input.accumulatedMinor, eligibleDays: 0, denominatorDays: 0, fractionNumerator: 0, fractionDenominator: 1 };
  let amount: number; let eligibleDays = inclusiveDays(start, end); let denominatorDays = 0; let fractionNumerator = eligibleDays; let fractionDenominator = 1;
  if (input.prorataConvention === "DAILY_ACTUAL_365" || input.prorataConvention === "DAILY_ACTUAL_366") {
    denominatorDays = input.usefulLifeMonths * (input.prorataConvention === "DAILY_ACTUAL_366" ? 366 : 365) / 12;
    fractionDenominator = Math.max(1, Math.round(denominatorDays));
    amount = roundPaise(depreciable * eligibleDays, fractionDenominator, input.roundingPolicy);
  } else {
    const monthStart = `${start.slice(0, 7)}-01`; const monthEnd = `${end.slice(0, 7)}-01`;
    const months = (Number(monthEnd.slice(0, 4)) - Number(monthStart.slice(0, 4))) * 12 + Number(monthEnd.slice(5, 7)) - Number(monthStart.slice(5, 7)) + 1;
    fractionNumerator = months; fractionDenominator = input.usefulLifeMonths;
    amount = roundPaise(depreciable * months, input.usefulLifeMonths, input.roundingPolicy);
  }
  if (input.method === "REDUCING_BALANCE") {
    if (!input.reducingRateBps || input.reducingRateBps <= 0 || input.reducingRateBps > 10000) throw new DomainError("INVALID_DEPRECIATION_POLICY", "reducing-balance policy requires reducingRateBps");
    const carrying = input.costMinor - input.accumulatedMinor;
    const annual = roundPaise(carrying * input.reducingRateBps, 10000, input.roundingPolicy);
    amount = input.prorataConvention === "MONTHLY" || input.prorataConvention === "FULL_MONTH" ? roundPaise(annual * fractionNumerator, 12, input.roundingPolicy) : roundPaise(annual * eligibleDays, input.prorataConvention === "DAILY_ACTUAL_366" ? 366 : 365, input.roundingPolicy);
  }
  const remaining = depreciable - input.accumulatedMinor;
  amount = Math.max(0, Math.min(amount, remaining));
  return { amountMinor: amount, closingAccumulatedMinor: input.accumulatedMinor + amount, eligibleDays, denominatorDays, fractionNumerator, fractionDenominator };
}

async function idempotency(session: BusinessSession, tenantId: TenantId, requestId: string): Promise<StoredIdempotency | undefined> { const row = await session.querySingle("SELECT request_hash, result_json, result_hash FROM idempotency_records WHERE tenant_id = ? AND request_id = ?", [tenantId, requestId]); return row ? { requestHash: String(row.request_hash), resultJson: String(row.result_json), resultHash: String(row.result_hash) } : undefined; }
async function replay<P>(session: BusinessSession, envelope: ScopedEnvelope<P>, hash: string): Promise<CommandResult<never> | undefined> { const existing = await idempotency(session, envelope.tenantId, envelope.requestId); if (!existing) return undefined; if (existing.requestHash !== hash) throw new IdempotencyConflictError("same request_id with different request hash"); if (computeResultHash(existing.resultJson) !== existing.resultHash) throw new IdempotencyCorruptError("stored result_json hash mismatch"); return { resultJson: existing.resultJson, resultHash: existing.resultHash, replayed: true }; }
async function finish<T>(session: BusinessSession, envelope: ScopedEnvelope<unknown>, command: string, hash: string, result: T, now: string): Promise<CommandResult<T>> { const resultJson = canonicalJson(result); const resultHash = computeResultHash(resultJson); await session.execute("INSERT INTO audit_records (id, tenant_id, book_set_id, command, action, actor_type, actor_id, source, reason, request_id, canonical_after_hash, change_summary, committed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId ?? null, command, command, envelope.actor.kind, envelope.actor.id, envelope.source, envelope.reason, envelope.requestId, resultHash, JSON.stringify(result), now, now]); await session.execute("INSERT INTO idempotency_records (id, tenant_id, request_id, request_hash, result_json, result_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.requestId, hash, resultJson, resultHash, now]); return { resultJson, resultHash }; }
async function bookSet(session: BusinessSession, tenantId: TenantId, bookSetId: BookSetId): Promise<string> { const row = await session.querySingle("SELECT kind, lifecycle FROM book_sets WHERE id = ? AND tenant_id = ?", [bookSetId, tenantId]); if (!row) throw new DomainError("BOOK_SET_NOT_FOUND", "BookSet does not belong to tenant"); if (String(row.lifecycle) !== "ACTIVE") throw new DomainError("BOOK_SET_INACTIVE", "BookSet must be ACTIVE"); return String(row.kind); }
async function account(session: BusinessSession, tenantId: TenantId, bookSetId: BookSetId, id: string, field: string): Promise<Record<string, unknown>> { const row = await session.querySingle("SELECT id, account_type, archived_at FROM accounts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, tenantId, bookSetId]); if (!row) throw new DomainError("ACCOUNT_SCOPE_MISMATCH", `${field} does not belong to tenant and BookSet`); if (row.archived_at != null) throw new DomainError("ACCOUNT_ARCHIVED", `${field} is archived`); return row; }
function validatePolicy(policy: AssetBookPolicyPayload): void { boundedText(policy.sourceReference, "bookPolicy.sourceReference"); boundedText(policy.justification, "bookPolicy.justification"); date(policy.effectiveFrom, "bookPolicy.effectiveFrom"); if (policy.effectiveTo) date(policy.effectiveTo, "bookPolicy.effectiveTo"); positive(policy.usefulLifeMonths, "bookPolicy.usefulLifeMonths"); nonnegative(policy.residualMinor, "bookPolicy.residualMinor"); if (policy.reducingRateBps !== undefined && (policy.reducingRateBps <= 0 || policy.reducingRateBps > 10000 || !Number.isSafeInteger(policy.reducingRateBps))) throw new DomainError("INVALID_DEPRECIATION_POLICY", "reducingRateBps must be between 1 and 10000"); if (policy.method === "REDUCING_BALANCE" && policy.reducingRateBps === undefined) throw new DomainError("INVALID_DEPRECIATION_POLICY", "reducing-balance policy requires reducingRateBps"); }

export async function executeAssetRegister(sessionRunner: BusinessSessionRunner, envelope: ScopedEnvelope<AssetRegisterPayload>): Promise<CommandResult<AssetRegisterResult>> {
  assertEnvelope(envelope); const p = envelope.payload; boundedText(p.assetNumber, "assetNumber"); boundedText(p.description, "description"); date(p.acquisitionDate, "acquisitionDate"); date(p.putToUseDate, "putToUseDate"); if (p.putToUseDate < p.acquisitionDate) throw new DomainError("INVALID_DATE", "putToUseDate must not precede acquisitionDate"); positive(p.costMinor, "costMinor"); if (!Number.isSafeInteger(p.businessUseBps) || p.businessUseBps < 1 || p.businessUseBps > 10000) throw new DomainError("INVALID_BUSINESS_USE", "businessUseBps must be between 1 and 10000"); validatePolicy(p.bookPolicy); if (p.evidenceReference !== undefined) boundedText(p.evidenceReference, "evidenceReference");
  if (p.vendorBillLineId === undefined && p.acquisitionJournalId === undefined) throw new DomainError("ASSET_EVIDENCE_REQUIRED", "manual asset registration requires acquisitionJournalId and evidenceReference"); if (p.vendorBillLineId === undefined && p.evidenceReference === undefined) throw new DomainError("ASSET_EVIDENCE_REQUIRED", "manual asset registration requires evidenceReference");
  if (p.components) { if (p.components.length === 0) throw new DomainError("INVALID_COMPONENTS", "components must not be empty"); const sum = p.components.reduce((n, c, i) => { boundedText(c.description, `components[${i}].description`); positive(c.costMinor, `components[${i}].costMinor`); nonnegative(c.residualMinor, `components[${i}].residualMinor`); positive(c.usefulLifeMonths, `components[${i}].usefulLifeMonths`); if (c.residualMinor > c.costMinor) throw new DomainError("INVALID_COMPONENTS", "component residual cannot exceed cost"); const rate = c.reducingRateBps; if (c.method === "REDUCING_BALANCE" && (typeof rate !== "number" || !Number.isSafeInteger(rate) || rate <= 0 || rate > 10000)) throw new DomainError("INVALID_COMPONENTS", "reducing-balance components require reducingRateBps between 1 and 10000"); if (c.method === "STRAIGHT_LINE" && rate !== undefined) throw new DomainError("INVALID_COMPONENTS", "straight-line components must not provide reducingRateBps"); return safeAdd(n, c.costMinor); }, 0); if (sum !== p.costMinor) throw new DomainError("COMPONENT_COST_MISMATCH", "component costs must exactly reconcile to asset cost"); }
  const hash = computeCommandHash("asset.register", envelope, p);
  return sessionRunner.withBusinessSession("write", async (session) => { const re = await replay(session, envelope, hash); if (re) return re as CommandResult<AssetRegisterResult>; const kind = await bookSet(session, envelope.tenantId, envelope.bookSetId); if ((kind === "COMPANY" || kind === "PERSONAL" || kind === "PROPRIETORSHIP") && p.businessUseBps === undefined) throw new DomainError("BUSINESS_USE_REQUIRED", "businessUseBps must be explicitly supplied"); for (const [id, field] of [[p.assetAccountId, "assetAccountId"], [p.accumulatedDepreciationAccountId, "accumulatedDepreciationAccountId"], [p.depreciationExpenseAccountId, "depreciationExpenseAccountId"], [p.gainLossAccountId, "gainLossAccountId"]] as const) await account(session, envelope.tenantId, envelope.bookSetId, id, field);
    if (p.vendorBillLineId) { const line = await session.querySingle("SELECT vbl.amount_minor, vbl.expense_account_id, vb.status, vb.total_minor, vb.gst_input_json FROM vendor_bill_lines vbl JOIN vendor_bills vb ON vb.id = vbl.bill_id AND vb.tenant_id = vbl.tenant_id AND vb.book_set_id = vbl.book_set_id WHERE vbl.id = ? AND vbl.tenant_id = ? AND vbl.book_set_id = ?", [p.vendorBillLineId, envelope.tenantId, envelope.bookSetId]); if (!line || !["POSTED", "PARTIALLY_PAID", "PAID"].includes(String(line.status))) throw new DomainError("ASSET_SOURCE_NOT_POSTED", "linked vendor bill line must belong to a posted bill"); if (String(line.expense_account_id) !== p.assetAccountId) throw new DomainError("ASSET_ACCOUNT_MISMATCH", "linked bill line must post to the asset account"); let expected = Number(line.amount_minor); if (line.gst_input_json) { try { const gst = JSON.parse(String(line.gst_input_json)) as { lines?: Array<{ lineNumber?: number; itcTreatment?: string; taxMinor?: number }> }; const taxes = (gst.lines ?? []).filter((x) => x.lineNumber === undefined || x.lineNumber === 1).reduce((n, x) => safeAdd(n, Number(x.taxMinor ?? 0)), 0); const ineligible = (gst.lines ?? []).some((x) => x.itcTreatment === "INELIGIBLE"); if (ineligible) expected = safeAdd(expected, taxes); } catch { throw new DomainError("INVALID_GST_FACTS", "linked bill GST facts are malformed"); } } if (expected !== p.costMinor) throw new DomainError("ASSET_SOURCE_AMOUNT_MISMATCH", "asset cost does not match linked bill line and GST ITC treatment"); }
    if (p.acquisitionJournalId) { const j = await session.querySingle("SELECT id FROM journal_entries WHERE id = ? AND tenant_id = ? AND book_set_id = ? AND status = 'POSTED'", [p.acquisitionJournalId, envelope.tenantId, envelope.bookSetId]); if (!j) throw new DomainError("ACQUISITION_JOURNAL_REQUIRED", "acquisitionJournalId must reference a posted journal"); const line = await session.querySingle("SELECT id FROM journal_lines WHERE journal_entry_id = ? AND tenant_id = ? AND book_set_id = ? AND account_id = ? AND debit_minor = ?", [p.acquisitionJournalId, envelope.tenantId, envelope.bookSetId, p.assetAccountId, p.costMinor]); if (!line) throw new DomainError("ACQUISITION_JOURNAL_MISMATCH", "posted acquisition journal must debit the asset account for the capitalized cost"); }
    const policyId = randomUUID(); const assetId = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO asset_book_policies (id, tenant_id, book_set_id, framework, source_reference, effective_from, effective_to, method, useful_life_months, residual_minor, prorata_convention, rounding_policy, remainder_policy, reducing_rate_bps, justification, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [policyId, envelope.tenantId, envelope.bookSetId, p.bookPolicy.framework, p.bookPolicy.sourceReference, p.bookPolicy.effectiveFrom, p.bookPolicy.effectiveTo ?? null, p.bookPolicy.method, p.bookPolicy.usefulLifeMonths, p.bookPolicy.residualMinor, p.bookPolicy.prorataConvention, p.bookPolicy.roundingPolicy, p.bookPolicy.remainderPolicy, p.bookPolicy.reducingRateBps ?? null, p.bookPolicy.justification, now]); await session.execute("INSERT INTO fixed_assets (id, tenant_id, book_set_id, asset_number, acquisition_date, put_to_use_date, description, category, location, custodian, cost_minor, business_use_bps, asset_account_id, accumulated_depreciation_account_id, depreciation_expense_account_id, gain_loss_account_id, book_policy_id, tax_block_id, source_vendor_bill_line_id, acquisition_journal_id, evidence_reference, status, disposed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ACTIVE', NULL, ?)", [assetId, envelope.tenantId, envelope.bookSetId, p.assetNumber, p.acquisitionDate, p.putToUseDate, p.description, p.category ?? null, p.location ?? null, p.custodian ?? null, p.costMinor, p.businessUseBps, p.assetAccountId, p.accumulatedDepreciationAccountId, p.depreciationExpenseAccountId, p.gainLossAccountId, policyId, p.taxBlockId ?? null, p.vendorBillLineId ?? null, p.acquisitionJournalId ?? null, p.evidenceReference ?? null, now]); for (const [i, c] of (p.components ?? []).entries()) await session.execute("INSERT INTO asset_components (id, tenant_id, book_set_id, asset_id, component_number, description, cost_minor, residual_minor, useful_life_months, method, reducing_rate_bps, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, assetId, i + 1, c.description, c.costMinor, c.residualMinor, c.usefulLifeMonths, c.method, c.reducingRateBps ?? null, now]); return finish(session, envelope, "asset.register", hash, { assetId, assetNumber: p.assetNumber, costMinor: p.costMinor, status: "ACTIVE" }, now); });
}

async function loadDepLines(session: BusinessSession, tenantId: TenantId, bookSetId: BookSetId, periodStart: string, periodEnd: string): Promise<DepreciationLineResult[]> {
  const assets = await session.query("SELECT a.*, p.method, p.useful_life_months, p.residual_minor, p.prorata_convention, p.rounding_policy, p.reducing_rate_bps FROM fixed_assets a JOIN asset_book_policies p ON p.id = a.book_policy_id AND p.tenant_id = a.tenant_id AND p.book_set_id = a.book_set_id WHERE a.tenant_id = ? AND a.book_set_id = ? AND a.status = 'ACTIVE' AND a.put_to_use_date <= ? ORDER BY a.asset_number, a.id", [tenantId, bookSetId, periodEnd]);
  const result: DepreciationLineResult[] = [];
  for (const a of assets.rows) {
    const components = await session.query("SELECT id, description, cost_minor, residual_minor, useful_life_months, method, reducing_rate_bps FROM asset_components WHERE asset_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY component_number", [a.id, tenantId, bookSetId]);
    const parts = components.rows.length ? components.rows.map((c) => ({ id: String(c.id), cost: Number(c.cost_minor), residual: Number(c.residual_minor), life: Number(c.useful_life_months), method: String(c.method) as BookPolicyMethod, reducingRateBps: c.reducing_rate_bps == null ? undefined : Number(c.reducing_rate_bps) })) : [{ id: undefined, cost: Number(a.cost_minor), residual: Number(a.residual_minor), life: Number(a.useful_life_months), method: String(a.method) as BookPolicyMethod, reducingRateBps: a.reducing_rate_bps == null ? undefined : Number(a.reducing_rate_bps) }];
    for (const part of parts) {
      const priorRows = await session.query("SELECT dl.amount_minor FROM asset_depreciation_lines dl JOIN asset_depreciation_runs dr ON dr.id = dl.run_id AND dr.tenant_id = dl.tenant_id AND dr.book_set_id = dl.book_set_id WHERE dl.asset_id = ? AND dl.component_id IS ? AND dl.tenant_id = ? AND dl.book_set_id = ? AND dr.status = 'POSTED' AND dr.period_end < ?", [a.id, part.id ?? null, tenantId, bookSetId, periodStart]);
      const prior = priorRows.rows.reduce((n, row) => safeAdd(n, Number(row.amount_minor)), 0);
      const calc = calculateBookDepreciation({ costMinor: part.cost, residualMinor: part.residual, accumulatedMinor: prior, method: part.method, usefulLifeMonths: part.life, reducingRateBps: part.reducingRateBps, periodStart, periodEnd, putToUseDate: String(a.put_to_use_date), prorataConvention: String(a.prorata_convention) as ProrataConvention, roundingPolicy: String(a.rounding_policy) as RoundingPolicy });
      if (calc.amountMinor > 0) result.push({ assetId: String(a.id), assetNumber: String(a.asset_number), amountMinor: calc.amountMinor, openingAccumulatedMinor: prior, closingAccumulatedMinor: calc.closingAccumulatedMinor, calculationFacts: { method: part.method, usefulLifeMonths: part.life, residualMinor: part.residual, eligibleDays: calc.eligibleDays, denominatorDays: calc.denominatorDays, fractionNumerator: calc.fractionNumerator, fractionDenominator: calc.fractionDenominator, componentId: part.id ?? null } });
    }
  }
  return result;
}

export async function executeDepreciation(sessionRunner: BusinessSessionRunner, envelope: ScopedEnvelope<DepreciationPreviewPayload>, post: boolean): Promise<CommandResult<DepreciationResult>> { assertEnvelope(envelope); date(envelope.payload.periodStart, "periodStart"); date(envelope.payload.periodEnd, "periodEnd"); if (envelope.payload.periodEnd < envelope.payload.periodStart) throw new DomainError("INVALID_PERIOD", "periodEnd must not precede periodStart"); const hash = computeCommandHash(post ? "asset.depreciation.post" : "asset.depreciation.preview", envelope, envelope.payload); return sessionRunner.withBusinessSession("write", async (session) => { const re = await replay(session, envelope, hash); if (re) return re as CommandResult<DepreciationResult>; await bookSet(session, envelope.tenantId, envelope.bookSetId); if (post) { const overlap = await session.querySingle("SELECT id FROM asset_depreciation_runs WHERE tenant_id = ? AND book_set_id = ? AND status = 'POSTED' AND period_start <= ? AND period_end >= ?", [envelope.tenantId, envelope.bookSetId, envelope.payload.periodEnd, envelope.payload.periodStart]); if (overlap) throw new DomainError("DEPRECIATION_PERIOD_OVERLAP", "depreciation period overlaps an existing posted run"); } const lines = await loadDepLines(session, envelope.tenantId, envelope.bookSetId, envelope.payload.periodStart, envelope.payload.periodEnd); let total = 0; for (const line of lines) total = safeAdd(total, line.amountMinor); const runId = randomUUID(); const calcHash = createHash("sha256").update(canonicalJson(lines)).digest("hex"); let journalId: string | undefined; const now = new Date().toISOString(); if (post && total > 0) { const journalLines: Array<{ accountId: ReturnType<typeof brandAccountId>; description: string; debitMinor?: number; creditMinor?: number }> = []; for (const line of lines) { const asset = await session.querySingle("SELECT depreciation_expense_account_id, accumulated_depreciation_account_id FROM fixed_assets WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [line.assetId, envelope.tenantId, envelope.bookSetId]); if (!asset) throw new DomainError("ASSET_SCOPE_MISMATCH", "asset does not belong to tenant and BookSet"); journalLines.push({ accountId: brandAccountId(String(asset.depreciation_expense_account_id)), description: `Depreciation ${line.assetNumber}`, debitMinor: line.amountMinor }); journalLines.push({ accountId: brandAccountId(String(asset.accumulated_depreciation_account_id)), description: `Accumulated depreciation ${line.assetNumber}`, creditMinor: line.amountMinor }); } journalId = await postJournalInSession(session, { tenantId: envelope.tenantId, bookSetId: envelope.bookSetId, postingDate: envelope.payload.periodEnd, reference: runId, narration: `Fixed asset depreciation ${envelope.payload.periodStart} to ${envelope.payload.periodEnd}`, lines: journalLines }); } const runStatus = post ? (total > 0 ? "POSTED" : "NO_OP") : "PREVIEW"; await session.execute("INSERT INTO asset_depreciation_runs (id, tenant_id, book_set_id, period_start, period_end, status, calculation_hash, journal_id, created_at, posted_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [runId, envelope.tenantId, envelope.bookSetId, envelope.payload.periodStart, envelope.payload.periodEnd, runStatus, calcHash, journalId ?? null, now, post && total > 0 ? now : null]); for (const line of lines) await session.execute("INSERT INTO asset_depreciation_lines (id, tenant_id, book_set_id, run_id, asset_id, component_id, amount_minor, opening_accumulated_minor, closing_accumulated_minor, calculation_facts_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, runId, line.assetId, line.calculationFacts.componentId ?? null, line.amountMinor, line.openingAccumulatedMinor, line.closingAccumulatedMinor, canonicalJson(line.calculationFacts), now]); const result: DepreciationResult = { runId, periodStart: envelope.payload.periodStart, periodEnd: envelope.payload.periodEnd, totalMinor: total, status: runStatus, ...(journalId ? { journalId } : {}), lines }; return finish(session, envelope, post ? "asset.depreciation.post" : "asset.depreciation.preview", hash, result, now); }); }

export async function executeAssetTaxRule(sessionRunner: BusinessSessionRunner, envelope: CommandEnvelope<AssetTaxRulePayload>): Promise<CommandResult<TaxRuleResult>> { validateCommandEnvelope(envelope); const p = envelope.payload; boundedText(p.lawName, "lawName"); boundedText(p.ruleReference, "ruleReference"); boundedText(p.version, "version"); boundedText(p.sourceUrl, "sourceUrl"); if (!p.sourceUrl.startsWith("https://")) throw new DomainError("INVALID_SOURCE_URL", "sourceUrl must use https"); date(p.effectiveFrom, "effectiveFrom"); if (p.effectiveTo) date(p.effectiveTo, "effectiveTo"); boundedText(p.blockCode, "blockCode"); if (!Number.isSafeInteger(p.rateBps) || p.rateBps < 0 || p.rateBps > 10000) throw new DomainError("INVALID_TAX_RATE", "rateBps must be between 0 and 10000"); boundedText(p.halfRateCondition, "halfRateCondition"); if (!p.sourceVerified) throw new DomainError("TAX_RULE_NOT_VERIFIED", "fixed-asset tax rules require sourceVerified"); const facts = p.calculationFacts ?? {}; const canonicalFacts = canonicalJson({ ...p, calculationFacts: facts }); const canonicalHash = createHash("sha256").update(canonicalFacts).digest("hex"); const hash = computeCommandHash("asset.tax-rule.create", envelope, p); return sessionRunner.withBusinessSession("write", async (session) => { const re = await replay(session, envelope as ScopedEnvelope<AssetTaxRulePayload>, hash); if (re) return re as CommandResult<TaxRuleResult>; await bookSet(session, envelope.tenantId, (p as AssetTaxRulePayload & { bookSetId?: BookSetId }).bookSetId ?? ("" as BookSetId)).catch(() => undefined); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO asset_tax_rule_snapshots (id, tenant_id, law_name, rule_reference, version, source_url, effective_from, effective_to, block_code, rate_bps, half_rate_condition, calculation_facts_json, source_verified, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, p.lawName, p.ruleReference, p.version, p.sourceUrl, p.effectiveFrom, p.effectiveTo ?? null, p.blockCode, p.rateBps, p.halfRateCondition, canonicalFacts, 1, canonicalHash, now]); return finish(session, envelope as ScopedEnvelope<unknown>, "asset.tax-rule.create", hash, { ruleSnapshotId: id, blockCode: p.blockCode, canonicalHash }, now); }); }

export async function executeTaxBlock(sessionRunner: BusinessSessionRunner, envelope: ScopedEnvelope<TaxBlockPayload>): Promise<CommandResult<TaxBlockResult>> { assertEnvelope(envelope); const p = envelope.payload; boundedText(p.blockCode, "blockCode"); boundedText(p.ruleSnapshotId, "ruleSnapshotId"); nonnegative(p.openingWdvMinor, "openingWdvMinor"); const hash = computeCommandHash("asset.tax-block.register", envelope, p); return sessionRunner.withBusinessSession("write", async (session) => { const re = await replay(session, envelope, hash); if (re) return re as CommandResult<TaxBlockResult>; await bookSet(session, envelope.tenantId, envelope.bookSetId); const rule = await session.querySingle("SELECT id, block_code FROM asset_tax_rule_snapshots WHERE id = ? AND tenant_id = ?", [p.ruleSnapshotId, envelope.tenantId]); if (!rule || String(rule.block_code) !== p.blockCode) throw new DomainError("TAX_RULE_SCOPE_MISMATCH", "tax block must use a rule snapshot for the same block code"); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO asset_tax_blocks (id, tenant_id, book_set_id, block_code, rule_snapshot_id, opening_wdv_minor, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.blockCode, p.ruleSnapshotId, p.openingWdvMinor, now]); return finish(session, envelope, "asset.tax-block.register", hash, { blockId: id, blockCode: p.blockCode, openingWdvMinor: p.openingWdvMinor }, now); }); }

function halfRateForAsset(condition: string, facts: Record<string, unknown>, asset: Record<string, unknown>, periodStart: string, supplied: { halfRate: boolean } | undefined): boolean {
  if (supplied) return supplied.halfRate;
  if (condition === "NONE") return false;
  if (condition === "CALLER_FACT") throw new DomainError("TAX_CALCULATION_FACTS_REQUIRED", "tax half-rate result must be supplied as a caller fact");
  const match = /^PUT_TO_USE_AFTER_DAYS$/.test(condition) ? Number(facts.halfRateDays) : NaN;
  if (!Number.isSafeInteger(match) || match < 0) throw new DomainError("TAX_RULE_FACTS_UNSUPPORTED", "tax snapshot does not contain a supported half-rate condition fact");
  return inclusiveDays(periodStart, String(asset.put_to_use_date)) > match;
}

export async function executeTaxCompute(sessionRunner: BusinessSessionRunner, envelope: ScopedEnvelope<TaxComputePayload>): Promise<CommandResult<TaxRunResult>> {
  assertEnvelope(envelope); date(envelope.payload.periodStart, "periodStart"); date(envelope.payload.periodEnd, "periodEnd"); if (envelope.payload.periodEnd < envelope.payload.periodStart) throw new DomainError("INVALID_PERIOD", "periodEnd must not precede periodStart");
  const hash = computeCommandHash("asset.tax.compute", envelope, envelope.payload);
  return sessionRunner.withBusinessSession("write", async (session) => {
    const re = await replay(session, envelope, hash); if (re) return re as CommandResult<TaxRunResult>; await bookSet(session, envelope.tenantId, envelope.bookSetId);
    const existing = await session.querySingle("SELECT id FROM asset_tax_runs WHERE tenant_id = ? AND book_set_id = ? AND period_start = ? AND period_end = ?", [envelope.tenantId, envelope.bookSetId, envelope.payload.periodStart, envelope.payload.periodEnd]); if (existing) throw new DomainError("TAX_PERIOD_ALREADY_COMPUTED", "tax period already has an immutable computation");
    const blocks = await session.query("SELECT b.id, b.block_code, b.opening_wdv_minor, r.rate_bps, r.half_rate_condition, r.calculation_facts_json, r.id AS rule_id, r.effective_from, r.effective_to FROM asset_tax_blocks b JOIN asset_tax_rule_snapshots r ON r.id = b.rule_snapshot_id AND r.tenant_id = b.tenant_id WHERE b.tenant_id = ? AND b.book_set_id = ? ORDER BY b.block_code, b.id", [envelope.tenantId, envelope.bookSetId]);
    if (blocks.rows.length === 0) throw new DomainError("TAX_RULE_MISSING", "no tax block and source-verified rule is registered");
    const lines: TaxLineResult[] = [];
    for (const block of blocks.rows) {
      const effectiveFrom = String(block.effective_from); const effectiveTo = block.effective_to == null ? undefined : String(block.effective_to); if (envelope.payload.periodStart < effectiveFrom || (effectiveTo && envelope.payload.periodEnd > effectiveTo)) throw new DomainError("TAX_RULE_NOT_EFFECTIVE", "tax rule snapshot is not effective for the explicit tax period", { blockCode: block.block_code, ruleSnapshotId: block.rule_id });
      const facts = JSON.parse(String(block.calculation_facts_json || "{}")) as Record<string, unknown>;
      const assets = await session.query("SELECT id, cost_minor, business_use_bps, put_to_use_date FROM fixed_assets WHERE tenant_id = ? AND book_set_id = ? AND tax_block_id = ? AND acquisition_date >= ? AND acquisition_date <= ? ORDER BY asset_number, id", [envelope.tenantId, envelope.bookSetId, block.id, envelope.payload.periodStart, envelope.payload.periodEnd]);
      let full = 0; let half = 0; let use = 10000; const additions: Array<Record<string, unknown>> = [];
      for (const asset of assets.rows) { const amount = roundPaise(Number(asset.cost_minor) * Number(asset.business_use_bps), 10000, "PAISE_HALF_UP"); const halfRate = halfRateForAsset(String(block.half_rate_condition), facts, asset, envelope.payload.periodStart, envelope.payload.additionFacts?.[String(asset.id)]); if (halfRate) half = safeAdd(half, amount); else full = safeAdd(full, amount); use = Math.min(use, Number(asset.business_use_bps)); additions.push({ assetId: asset.id, amountMinor: amount, businessUseBps: asset.business_use_bps, putToUseDate: asset.put_to_use_date, halfRate }); }
      const disposals = await session.query("SELECT d.proceeds_minor FROM asset_disposals d JOIN fixed_assets a ON a.id = d.asset_id AND a.tenant_id = d.tenant_id AND a.book_set_id = d.book_set_id WHERE d.tenant_id = ? AND d.book_set_id = ? AND a.tax_block_id = ? AND d.disposal_date >= ? AND d.disposal_date <= ?", [envelope.tenantId, envelope.bookSetId, block.id, envelope.payload.periodStart, envelope.payload.periodEnd]);
      const consideration = disposals.rows.reduce((n, row) => safeAdd(n, Number(row.proceeds_minor)), 0); const opening = Number(block.opening_wdv_minor); const preDep = opening + full + half - consideration; const negative = preDep < 0; const wdv = Math.max(0, preDep); const rate = Number(block.rate_bps); const beforeUse = roundPaise((wdv * rate), 10000, "PAISE_HALF_UP"); const dep = Math.min(wdv, Math.max(0, beforeUse)); const closing = wdv - dep; const cessation = consideration > 0 && closing === 0;
      lines.push({ blockId: String(block.id), blockCode: String(block.block_code), openingWdvMinor: opening, additionsFullMinor: full, additionsHalfMinor: half, businessUseBps: use, disposalConsiderationMinor: consideration, depreciationMinor: dep, closingWdvMinor: closing, cessation, negativeProceeds: negative, calculationFacts: { ruleSnapshotId: block.rule_id, rateBps: rate, halfRateCondition: block.half_rate_condition, additions } });
    }
    const runId = randomUUID(); const now = new Date().toISOString(); const calcHash = createHash("sha256").update(canonicalJson(lines)).digest("hex"); await session.execute("INSERT INTO asset_tax_runs (id, tenant_id, book_set_id, period_start, period_end, status, calculation_hash, created_at) VALUES (?, ?, ?, ?, ?, 'COMPUTED', ?, ?)", [runId, envelope.tenantId, envelope.bookSetId, envelope.payload.periodStart, envelope.payload.periodEnd, calcHash, now]); for (const line of lines) await session.execute("INSERT INTO asset_tax_run_lines (id, tenant_id, book_set_id, run_id, block_id, opening_wdv_minor, additions_full_minor, additions_half_minor, business_use_bps, disposal_consideration_minor, depreciation_minor, closing_wdv_minor, cessation, negative_proceeds, calculation_facts_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, runId, line.blockId, line.openingWdvMinor, line.additionsFullMinor, line.additionsHalfMinor, line.businessUseBps, line.disposalConsiderationMinor, line.depreciationMinor, line.closingWdvMinor, line.cessation ? 1 : 0, line.negativeProceeds ? 1 : 0, canonicalJson(line.calculationFacts), now]); return finish(session, envelope, "asset.tax.compute", hash, { runId, periodStart: envelope.payload.periodStart, periodEnd: envelope.payload.periodEnd, lines }, now);
  });
}

export async function executeAssetDispose(sessionRunner: BusinessSessionRunner, envelope: ScopedEnvelope<AssetDisposePayload>): Promise<CommandResult<AssetDisposeResult>> {
  assertEnvelope(envelope); const p = envelope.payload; boundedText(p.assetId, "assetId"); date(p.disposalDate, "disposalDate"); nonnegative(p.proceedsMinor, "proceedsMinor"); boundedText(p.proceedsAccountId, "proceedsAccountId"); boundedText(p.evidenceReference, "evidenceReference"); const hash = computeCommandHash("asset.dispose", envelope, p); return sessionRunner.withBusinessSession("write", async (session) => { const re = await replay(session, envelope, hash); if (re) return re as CommandResult<AssetDisposeResult>; await bookSet(session, envelope.tenantId, envelope.bookSetId); const asset = await session.querySingle("SELECT * FROM fixed_assets WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.assetId, envelope.tenantId, envelope.bookSetId]); if (!asset) throw new DomainError("ASSET_SCOPE_MISMATCH", "asset does not belong to tenant and BookSet"); if (String(asset.status) !== "ACTIVE") throw new DomainError("ASSET_ALREADY_DISPOSED", "asset is already disposed"); if (p.disposalDate < String(asset.put_to_use_date)) throw new DomainError("INVALID_DATE", "disposalDate must not precede putToUseDate"); await account(session, envelope.tenantId, envelope.bookSetId, p.proceedsAccountId, "proceedsAccountId"); const accumRows = await session.query("SELECT dl.amount_minor FROM asset_depreciation_lines dl JOIN asset_depreciation_runs dr ON dr.id = dl.run_id AND dr.tenant_id = dl.tenant_id AND dr.book_set_id = dl.book_set_id WHERE dl.asset_id = ? AND dl.tenant_id = ? AND dl.book_set_id = ? AND dr.status = 'POSTED'", [p.assetId, envelope.tenantId, envelope.bookSetId]); const accumulated = accumRows.rows.reduce((n, row) => safeAdd(n, Number(row.amount_minor)), 0); const carrying = Number(asset.cost_minor) - accumulated; const gainLoss = p.proceedsMinor - carrying; const lines: Array<{ accountId: ReturnType<typeof brandAccountId>; description: string; debitMinor?: number; creditMinor?: number }> = []; if (p.proceedsMinor > 0) lines.push({ accountId: brandAccountId(p.proceedsAccountId), description: `Disposal proceeds ${p.assetId}`, debitMinor: p.proceedsMinor }); if (accumulated > 0) lines.push({ accountId: brandAccountId(String(asset.accumulated_depreciation_account_id)), description: `Remove accumulated depreciation ${p.assetId}`, debitMinor: accumulated }); lines.push({ accountId: brandAccountId(String(asset.asset_account_id)), description: `Remove asset cost ${p.assetId}`, creditMinor: Number(asset.cost_minor) }); if (gainLoss > 0) lines.push({ accountId: brandAccountId(String(asset.gain_loss_account_id)), description: `Gain on disposal ${p.assetId}`, creditMinor: gainLoss }); else if (gainLoss < 0) lines.push({ accountId: brandAccountId(String(asset.gain_loss_account_id)), description: `Loss on disposal ${p.assetId}`, debitMinor: -gainLoss }); const journalId = await postJournalInSession(session, { tenantId: envelope.tenantId, bookSetId: envelope.bookSetId, postingDate: p.disposalDate, reference: p.assetId, narration: `Fixed asset disposal ${p.assetId}`, lines }); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO asset_disposals (id, tenant_id, book_set_id, asset_id, disposal_date, proceeds_minor, proceeds_account_id, carrying_amount_minor, gain_loss_minor, journal_id, evidence_reference, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.assetId, p.disposalDate, p.proceedsMinor, p.proceedsAccountId, carrying, gainLoss, journalId, p.evidenceReference, now]); await session.execute("UPDATE fixed_assets SET status = 'DISPOSED', disposed_at = ? WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.disposalDate, p.assetId, envelope.tenantId, envelope.bookSetId]); return finish(session, envelope, "asset.dispose", hash, { disposalId: id, assetId: p.assetId, carryingAmountMinor: carrying, gainLossMinor: gainLoss, journalId, status: "DISPOSED" }, now); });
}

export async function listAssetRegister(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, asOfDate?: string): Promise<AssetRegisterRow[]> {
  if (asOfDate) date(asOfDate, "asOfDate"); return sessionRunner.withBusinessSession("read", async (session) => { await bookSet(session, tenantId, bookSetId); const rows = await session.query("SELECT id, asset_number, acquisition_date, put_to_use_date, description, category, cost_minor, status, disposed_at FROM fixed_assets WHERE tenant_id = ? AND book_set_id = ? ORDER BY asset_number, id", [tenantId, bookSetId]); const result: AssetRegisterRow[] = []; for (const r of rows.rows) { if (asOfDate && String(r.acquisition_date) > asOfDate) continue; const depRows = await session.query("SELECT dl.amount_minor FROM asset_depreciation_lines dl JOIN asset_depreciation_runs dr ON dr.id = dl.run_id AND dr.tenant_id = dl.tenant_id AND dr.book_set_id = dl.book_set_id WHERE dl.asset_id = ? AND dl.tenant_id = ? AND dl.book_set_id = ? AND dr.status = 'POSTED' AND dr.period_end <= ?", [r.id, tenantId, bookSetId, asOfDate ?? "9999-12-31"]); const accumulated = depRows.rows.reduce((n, row) => safeAdd(n, Number(row.amount_minor)), 0); const cost = Number(r.cost_minor); result.push({ assetId: String(r.id), assetNumber: String(r.asset_number), acquisitionDate: String(r.acquisition_date), putToUseDate: String(r.put_to_use_date), description: String(r.description), ...(r.category == null ? {} : { category: String(r.category) }), costMinor: cost, accumulatedDepreciationMinor: accumulated, carryingAmountMinor: cost - accumulated, status: String(r.status), ...(r.disposed_at == null ? {} : { disposedAt: String(r.disposed_at) }) }); } return result; });
}

export async function listBookDepreciation(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, periodStart: string, periodEnd: string): Promise<DepreciationLineResult[]> { date(periodStart, "periodStart"); date(periodEnd, "periodEnd"); return sessionRunner.withBusinessSession("read", async (session) => { await bookSet(session, tenantId, bookSetId); const rows = await session.query("SELECT dl.asset_id, a.asset_number, dl.amount_minor, dl.opening_accumulated_minor, dl.closing_accumulated_minor, dl.calculation_facts_json FROM asset_depreciation_lines dl JOIN asset_depreciation_runs dr ON dr.id = dl.run_id AND dr.tenant_id = dl.tenant_id AND dr.book_set_id = dl.book_set_id JOIN fixed_assets a ON a.id = dl.asset_id AND a.tenant_id = dl.tenant_id AND a.book_set_id = dl.book_set_id WHERE dl.tenant_id = ? AND dl.book_set_id = ? AND dr.status = 'POSTED' AND dr.period_start >= ? AND dr.period_end <= ? ORDER BY dr.period_start, a.asset_number, dl.id", [tenantId, bookSetId, periodStart, periodEnd]); return rows.rows.map((r) => ({ assetId: String(r.asset_id), assetNumber: String(r.asset_number), amountMinor: Number(r.amount_minor), openingAccumulatedMinor: Number(r.opening_accumulated_minor), closingAccumulatedMinor: Number(r.closing_accumulated_minor), calculationFacts: JSON.parse(String(r.calculation_facts_json)) as Record<string, unknown> })); }); }

export async function listTaxSchedule(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, periodStart: string, periodEnd: string): Promise<TaxLineResult[]> { date(periodStart, "periodStart"); date(periodEnd, "periodEnd"); return sessionRunner.withBusinessSession("read", async (session) => { await bookSet(session, tenantId, bookSetId); const rows = await session.query("SELECT l.*, b.block_code FROM asset_tax_run_lines l JOIN asset_tax_runs r ON r.id = l.run_id AND r.tenant_id = l.tenant_id AND r.book_set_id = l.book_set_id JOIN asset_tax_blocks b ON b.id = l.block_id AND b.tenant_id = l.tenant_id AND b.book_set_id = l.book_set_id WHERE l.tenant_id = ? AND l.book_set_id = ? AND r.period_start = ? AND r.period_end = ? ORDER BY b.block_code, l.id", [tenantId, bookSetId, periodStart, periodEnd]); return rows.rows.map((r) => ({ blockId: String(r.block_id), blockCode: String(r.block_code), openingWdvMinor: Number(r.opening_wdv_minor), additionsFullMinor: Number(r.additions_full_minor), additionsHalfMinor: Number(r.additions_half_minor), businessUseBps: Number(r.business_use_bps), disposalConsiderationMinor: Number(r.disposal_consideration_minor), depreciationMinor: Number(r.depreciation_minor), closingWdvMinor: Number(r.closing_wdv_minor), cessation: Boolean(r.cessation), negativeProceeds: Boolean(r.negative_proceeds), calculationFacts: JSON.parse(String(r.calculation_facts_json)) as Record<string, unknown> })); }); }

export async function bookTaxReconciliation(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, periodStart: string, periodEnd: string): Promise<Array<{ assetId: string; assetNumber: string; bookDepreciationMinor: number; taxDepreciationMinor: number; differenceMinor: number }>> { const book = await listBookDepreciation(sessionRunner, tenantId, bookSetId, periodStart, periodEnd); const tax = await listTaxSchedule(sessionRunner, tenantId, bookSetId, periodStart, periodEnd); const taxTotal = tax.reduce((n, x) => n + x.depreciationMinor, 0); const byAsset = new Map<string, { assetNumber: string; book: number }>(); for (const row of book) { const prior = byAsset.get(row.assetId); byAsset.set(row.assetId, { assetNumber: row.assetNumber, book: (prior?.book ?? 0) + row.amountMinor }); } return [...byAsset.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([assetId, row]) => ({ assetId, assetNumber: row.assetNumber, bookDepreciationMinor: row.book, taxDepreciationMinor: byAsset.size === 1 ? taxTotal : 0, differenceMinor: row.book - (byAsset.size === 1 ? taxTotal : 0) })); }
